    await afterPendingWork();
    h.close();
    h.release(0);
    await Promise.all(sends);

    const {entries} = h.session;
    expect({
      asked: h.handed.length,
      entries: entries.map(entry => `${entry.role} ${'content' in entry ? entry.content : ''}`),
    }).toEqual({asked: 1, entries: ['user A', 'assistant answer 0']});
  });
});

describe('list_sessions', () => {
  it("answers the connection user's own sessions as one session_list with ISO dates", async () => {
    const listFor = jest.fn(async (..._args: unknown[]) => [
      {
        sessionId: 's2',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-01T00:02:00.000Z'),
        entryCount: 4,
      },
    ]);
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const handle = createMessageHandler({} as unknown as ChatOrchestrator, {listFor} as unknown as SessionStore);
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

    await handle(ws, session, {type: 'list_sessions', limit: 10});

    expect({asked: listFor.mock.calls, sent}).toEqual({
      asked: [['u1', {limit: 10}]],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
    });
  });

  it('answers SERVER_ERROR and logs the failure under ws when listFor rejects', async () => {
    const logged: Array<{level: string; category: string; fields?: Record<string, unknown>}> = [];
    const record = (level: string) => (category: string, _message: string, fields?: Record<string, unknown>) =>
      void logged.push({level, category, fields});
    setLogger({debug: record('debug'), info: record('info'), warn: record('warn'), error: record('error')});
    const listFor = jest.fn(async (..._args: unknown[]): Promise<never> => {
      throw new Error('database offline');
    });
    const sent: OutgoingMessage[] = [];
    const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
    const handle = createMessageHandler({} as unknown as ChatOrchestrator, {listFor} as unknown as SessionStore);
    const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};

    try {
      await handle(ws, session, {type: 'list_sessions'});
    } finally {
      setLogger();
    }

    expect({
      sent: sent.map(frame => ({type: frame.type, code: 'code' in frame ? frame.code : undefined})),
      logged: logged.filter(line => line.level === 'error' && line.category === 'ws'),
    }).toEqual({
      sent: [{type: 'error', code: 'SERVER_ERROR'}],
      logged: [
        {level: 'error', category: 'ws', fields: expect.objectContaining({userId: 'u1', error: 'database offline'})},
      ],
    });
  });
});

